// 演示·掷弹（内联效果·对象态）：unit.deployed → Host==载荷单位 → 对敌方一个单位造成 1 点伤害。
Func<Orc.Cards.CardEventView, Context, CancellationToken, Task> HandleAsync = async (view, ctx, ct) =>
{
    if (view.Unit is not Orc.Cards.Card deployed || !object.ReferenceEquals(deployed, view.Host))
    {
        return; // 非本单位部署：不处理（Host==载荷过滤）
    }

    var runtime = Orc.Game.Effects.EffectRuntime.ResolveFor(deployed);
    if (runtime is null)
    {
        return; // 无效果运行时：跳过（脱局场景）
    }

    var targets = await runtime.SelectAsync(deployed, new Orc.Game.Effects.EffectSelector("one", "enemy", null, null, null, null, null));
    foreach (var target in targets)
    {
        await runtime.DamageAsync(target, 1, deployed, ct);
    }
};
